import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { STATE_DIR } from "../config.mjs";

const LEDGER = path.join(STATE_DIR, "operations.jsonl");
// Enough to cover any plausible retry window, small enough that the file never becomes a
// second diary. Older lines are dropped on write.
const MAX_ENTRIES = 500;

// A consumed item's id is generated by the client, which makes it the idempotency key this API
// does not otherwise have. Deriving it from the operation key rather than at random is what
// makes a repeat harmless: the same logical write produces the same id, so a second POST can
// only overwrite its own entry, never create a twin. It also gives an uncertain write something
// to look for — read the day back and check whether that exact id is there.
//
// Shaped as a v4 UUID because that is what the app sends and what the API is known to accept;
// the bits are set accordingly even though the value is a hash rather than random.
export function deriveEntryId(operationKey) {
  const digest = crypto.createHash("sha256").update(String(operationKey), "utf8").digest();
  const bytes = Buffer.from(digest.subarray(0, 16));
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = bytes.toString("hex").toUpperCase();
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// Everything that identifies one logical write. Amount is included deliberately: logging 200 g
// after 150 g is a different entry, not a repeat of the same one.
export function operationKey({ operation, date, daytime, targetId, amount }) {
  return [operation, date, daytime, targetId, amount].join("|");
}

function ensureDir() {
  fs.mkdirSync(STATE_DIR, { recursive: true, mode: 0o700 });
  try { fs.chmodSync(STATE_DIR, 0o700); } catch {}
}

function readLines() {
  let text;
  try { text = fs.readFileSync(LEDGER, "utf8"); }
  catch (error) { if (error.code === "ENOENT") return []; throw error; }
  const lines = text.split("\n");
  if (text.endsWith("\n")) lines.pop();
  const records = [];
  for (const line of lines) {
    if (!line.trim()) continue;
    // A partial trailing line is what a crash mid-append leaves behind. Skipping it is right;
    // refusing to read the ledger at all would turn a torn write into a lost duplicate check.
    try { records.push(JSON.parse(line)); } catch { continue; }
  }
  return records;
}

export function findOperation(key) {
  const matches = readLines().filter((record) => record.operation_key === key && record.verified);
  return matches.length ? matches[matches.length - 1] : null;
}

export function recordOperation(record) {
  ensureDir();
  const line = { ...record, recorded_at: new Date().toISOString() };
  const existing = readLines();
  const kept = [...existing, line].slice(-MAX_ENTRIES);
  const temp = `${LEDGER}.${process.pid}.${Date.now()}.tmp`;
  let fd;
  try {
    fd = fs.openSync(temp, "wx", 0o600);
    fs.writeFileSync(fd, kept.map((item) => JSON.stringify(item)).join("\n") + "\n");
    fs.fsyncSync(fd);
    fs.closeSync(fd); fd = undefined;
    fs.renameSync(temp, LEDGER);
  } catch (error) {
    if (fd !== undefined) try { fs.closeSync(fd); } catch {}
    fs.rmSync(temp, { force: true });
    throw error;
  }
  return line;
}

export function ledgerPath() { return LEDGER; }
